```c
#include <stdio.h>

int popcount(int x) {
    int c = 0;
    while (x) {
        c += x & 1;
        x >>= 1;
    }
    return c;
}

int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    int P;
    scanf("%d", &P);

    int black[6][6] = {0};
    for (int i = 0; i < P; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        black[x - 1][y - 1] = 1;
    }

    int allowed[6] = {0};
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    for (int i = 0; i < L; i++) {
        for (int j = 0; j < C; j++) {
            if (black[i][j]) continue;

            int ok = 0;
            for (int d = 0; d < 4; d++) {
                int ni = i + dr[d];
                int nj = j + dc[d];
                if (ni >= 0 && ni < L && nj >= 0 && nj < C && black[ni][nj]) {
                    ok = 1;
                    break;
                }
            }

            if (ok) {
                allowed[i] |= (1 << j);
            }
        }
    }

    int totalMasks = 1 << C;
    int dp[64], ndp[64];

    for (int m = 0; m < totalMasks; m++) {
        dp[m] = -1000000;
    }
    dp[0] = 0;

    for (int i = 0; i < L; i++) {
        for (int m = 0; m < totalMasks; m++) {
            ndp[m] = -1000000;
        }

        for (int prev = 0; prev < totalMasks; prev++) {
            if (dp[prev] < 0) continue;

            for (int cur = 0; cur < totalMasks; cur++) {
                if ((cur & ~allowed[i]) != 0) continue;
                if ((cur & (cur << 1)) != 0) continue;
                if ((cur & prev) != 0) continue;

                int val = dp[prev] + popcount(cur);
                if (val > ndp[cur]) {
                    ndp[cur] = val;
                }
            }
        }

        for (int m = 0; m < totalMasks; m++) {
            dp[m] = ndp[m];
        }
    }

    int ans = 0;
    for (int m = 0; m < totalMasks; m++) {
        if (dp[m] > ans) ans = dp[m];
    }

    printf("%d\n", ans);
    return 0;
}
```

